"""Independent reference implementation of PROTOCOL.md (validator, LPM, image walker)."""
TYPE_CELLS = {1: 1, 2: 2, 3: 2, 4: 1, 5: 2}
BMP_NULL = 4194303
HOP_MAX = 4194302
ABSENT = 15 << 6

def mask(v, L):
    if L <= 0: return 0
    if L >= 128: return v & ((1 << 128) - 1)
    return v & ~((1 << (128 - L)) - 1)

def bits_at(v, off, cnt):
    if cnt <= 0: return 0
    if off >= 128: return 0
    m = (1 << cnt) - 1
    sh = 128 - off - cnt
    if sh >= 0: return (v >> sh) & m
    return (v << (-sh)) & m

def origin_of(L): return 0 if L <= 16 else (16 if L <= 64 else 64)
def omax(o): return 16 if o == 0 else (64 if o == 16 else 128)
def g(row, off, n): return (row >> off) & ((1 << n) - 1)

def lpm(prefixes, addr):
    """prefixes: list of (addr, len, hop) normalized."""
    best = None; bl = -1
    for (a, l, h) in prefixes:
        if mask(addr, l) == a and l > bl:
            best = h; bl = l
    return best

class Fail(Exception):
    pass

def validate_image(img, want_fib=False):
    """Return (ok, reason). reason is '' when ok."""
    try:
        fib = _validate(img)
        if want_fib: return (True, '', fib)
        return (True, '')
    except Fail as e:
        if want_fib: return (False, str(e), None)
        return (False, str(e))

def _validate(img):
    if set(img) != {'root', 'front16', 'front64', 'cells', 'banks', 'bitmaps', 'nexthops'}:
        raise Fail('keys')
    root = img['root']; f16 = img['front16']; f64 = img['front64']
    cells = img['cells']; banks = img['banks']
    bitmaps = img['bitmaps']; nexthops = img['nexthops']
    if len(cells) != 11 or len(banks) != 11: raise Fail('cells/banks length')
    rows = []
    total_rows = 0
    for s in range(11):
        if not (0 <= cells[s] <= 131072): raise Fail('cells bound')
        if len(banks[s]) != (cells[s] + 1) // 2: raise Fail('row count stage %d' % s)
        total_rows += len(banks[s])
        rows.append([int(w, 16) for w in banks[s]])
        for w in banks[s]:
            if len(w) != 64: raise Fail('word width')
    if total_rows > 65536: raise Fail('row total')
    if len(bitmaps) > 8193: raise Fail('bitmap bound')
    if len(nexthops) > 8192: raise Fail('ni bound')
    for h in nexthops:
        if not (isinstance(h, int) and 0 <= h <= HOP_MAX): raise Fail('ni hop value')
    if len(f16) > 4096 or len(f64) > 4096: raise Fail('front bound')
    if root is not None:
        if not (isinstance(root, list) and len(root) == 2): raise Fail('root shape')
        if not (0 <= root[0] <= 10 and 0 <= root[1] < cells[root[0]]): raise Fail('root locator')
    for lst, width in ((f16, 4), (f64, 16)):
        prev = None
        for e in lst:
            k = int(e[0], 16)
            if len(e[0]) != width: raise Fail('front key width')
            if prev is not None and not (prev < k): raise Fail('front order')
            prev = k
            if width == 4 and k > 0xFFFF: raise Fail('front16 key range')
            if not (0 <= e[1] <= 10): raise Fail('front stage')
            if not (0 <= e[2] < cells[e[1]]): raise Fail('front cell')

    cover = [[-1] * cells[s] for s in range(11)]
    nodes = []
    queue = []
    fib = []
    if root is not None:
        queue.append(dict(stage=root[0], cell=root[1], bulk=False, origin=0, depth=0, region=0, parent=-1))
    for e in f16:
        k = int(e[0], 16)
        queue.append(dict(stage=e[1], cell=e[2], bulk=False, origin=16, depth=16, region=k << 112, parent=-1))
    for e in f64:
        k = int(e[0], 16)
        queue.append(dict(stage=e[1], cell=e[2], bulk=False, origin=64, depth=64, region=k << 64, parent=-1))

    qi = 0
    while qi < len(queue):
        w = queue[qi]; qi += 1
        s = w['stage']; c = w['cell']
        if not (0 <= s <= 10): raise Fail('stage range')
        if c >= cells[s]: raise Fail('locator cell')
        mx = omax(w['origin'])
        if not (0 <= w['depth'] <= mx): raise Fail('depth range')
        if (w['depth'] - w['origin']) % 6: raise Fail('depth alignment')
        row = rows[s][c // 2]
        base = 128 if (c & 1) else 0
        t = g(row, base, 3)
        if t not in TYPE_CELLS: raise Fail('node type %d' % t)
        rec = TYPE_CELLS[t]
        if rec == 2 and (c & 1): raise Fail('full record alignment')
        slot = 2 if w['bulk'] else rec
        if c + slot > cells[s]: raise Fail('slot overflow')
        idx = len(nodes)
        for k in range(slot):
            if cover[s][c + k] != -1: raise Fail('overlap/duplicate node')
            cover[s][c + k] = idx
        if slot == 2 and rec == 1:
            if g(row, 128, 128) != 0: raise Fail('bulk padding not zero')
        n = dict(stage=s, cell=c, slot=slot, rec=rec, type=t, origin=w['origin'], depth=w['depth'],
                 region=w['region'], parent=w['parent'], bmp=g(row, base + 3, 22), children=[],
                 pattern=0, ni_base=0, ninl=[], owned=0)
        nodes.append(n)
        if len(fib) > 8192: raise Fail('prefix bound')

        if t <= 3:
            bid = g(row, base + 25, 16); nib = g(row, base + 41, 22)
            if bid >= len(bitmaps): raise Fail('bitmap id')
            pat = bitmaps[bid]
            if pat & 1: raise Fail('bitmap bit0')
            pc = bin(pat).count('1')
            if nib + pc > len(nexthops): raise Fail('ni range')
            if pc == 0 and nib != 0: raise Fail('empty ni base')
            n['pattern'] = pat; n['ni_base'] = nib; n['bitmap_id'] = bid
            if t == 1 and g(row, base + 127, 1) != 0: raise Fail('t1 reserved')
            if t == 2 and g(row, base + 255, 1) != 0: raise Fail('t2 reserved')
            if t == 3 and g(row, base + 249, 7) != 0: raise Fail('t3 reserved')

        nslots = {1: 2, 2: 6, 3: 3}.get(t, 0)
        cbase = {1: 63, 2: 63, 3: 153}.get(t, 0)
        direct = 0; last_key = -1; seen_absent = False
        for i in range(nslots):
            v = g(row, base + cbase + 32 * i, 32)
            key = v & 63; cst = (v >> 6) & 15; ccell = v >> 10
            if cst == 15:
                if v != ABSENT: raise Fail('absent encoding')
                seen_absent = True
                continue
            if cst > 10: raise Fail('child stage')
            if seen_absent: raise Fail('child order')
            if key <= last_key: raise Fail('child key order')
            last_key = key
            if cst >= s: raise Fail('child stage not lower')
            if w['depth'] + 6 > mx: raise Fail('child past max')
            direct |= 1 << key
            n['children'].append((key, cst, ccell))
            queue.append(dict(stage=cst, cell=ccell, bulk=False, origin=w['origin'], depth=w['depth'] + 6,
                              region=w['region'] | (key << (128 - w['depth'] - 6)), parent=idx))
        if t == 3:
            bm = g(row, base + 63, 64); bbase = g(row, base + 127, 22); bstg = g(row, base + 149, 4)
            if bstg > 10: raise Fail('bulk stage')
            if bstg >= s: raise Fail('bulk stage not lower')
            if bbase & 1: raise Fail('bulk base odd')
            bc = bin(bm).count('1')
            if bc < 4: raise Fail('bulk count')
            if bbase + 2 * bc > cells[bstg]: raise Fail('bulk overflow')
            if bm & direct: raise Fail('bulk/direct overlap')
            if w['depth'] + 6 > mx: raise Fail('bulk past max')
            i = 0
            for k in range(64):
                if not (bm >> k) & 1: continue
                n['children'].append((k, bstg, bbase + 2 * i))
                queue.append(dict(stage=bstg, cell=bbase + 2 * i, bulk=True, origin=w['origin'],
                                  depth=w['depth'] + 6,
                                  region=w['region'] | (k << (128 - w['depth'] - 6)), parent=idx))
                i += 1
        nc = len(n['children'])
        if t == 2 and not (3 <= nc <= 6): raise Fail('type2 children %d' % nc)
        if t == 3 and not (7 <= nc <= 64): raise Fail('type3 children %d' % nc)
        if t == 1 and nc > 2: raise Fail('type1 children')

        if t in (4, 5):
            ninl = 1 if t == 4 else 2
            if t == 4 and g(row, base + 119, 9) != 0: raise Fail('t4 reserved')
            if t == 5 and g(row, base + 213, 43) != 0: raise Fail('t5 reserved')
            for i in range(ninl):
                pos = base + (25 if i == 0 else 119)
                frag = g(row, pos, 64); l8 = g(row, pos + 64, 8); hop = g(row, pos + 86, 22)
                if hop > HOP_MAX: raise Fail('inline hop')
                if w['origin'] == 0:
                    if l8 > 16: raise Fail('inline len origin0')
                    a = frag << 64; L = l8
                elif w['origin'] == 16:
                    if not (1 <= l8 <= 48): raise Fail('inline len origin16')
                    key16 = bits_at(w['region'], 0, 16)
                    a = (key16 << 112) | ((frag >> 16) << 64); L = 16 + l8
                else:
                    if not (1 <= l8 <= 64): raise Fail('inline len origin64')
                    a = (bits_at(w['region'], 0, 64) << 64) | frag; L = 64 + l8
                if mask(a, L) != a: raise Fail('inline host bits')
                if L < w['depth']: raise Fail('inline shorter than depth')
                if L > mx: raise Fail('inline past max')
                if mask(a, w['depth']) != w['region']: raise Fail('inline outside region')
                n['ninl'].append((a, L, hop))
                fib.append((a, L, hop))
                if len(fib) > 8192: raise Fail('prefix bound')
        else:
            minL = {0: 0, 16: 17, 64: 65}[w['origin']]
            off = 0
            for p in range(1, 64):
                if not (n['pattern'] >> p) & 1: continue
                l = p.bit_length() - 1
                v = p - (1 << l)
                L = w['depth'] + l
                if L > mx or L < minL: raise Fail('ni ownership')
                a = w['region'] | (v << (128 - L) if l else 0)
                if mask(a, L) != a: raise Fail('ni normalization')
                hop = nexthops[n['ni_base'] + off]; off += 1
                fib.append((a, L, hop))
                if len(fib) > 8192: raise Fail('prefix bound')

    # dense coverage
    for s in range(11):
        for c in range(cells[s]):
            if cover[s][c] < 0: raise Fail('hole in stage %d cell %d' % (s, c))
        if cells[s] & 1:
            if g(rows[s][cells[s] // 2], 128, 128) != 0: raise Fail('final upper half')
    # child locators resolve exactly
    for n in nodes:
        for (key, cs, cc) in n['children']:
            if cc >= cells[cs]: raise Fail('child cell bound')
            nid = cover[cs][cc]
            if nid < 0: raise Fail('child unresolved')
            if nodes[nid]['cell'] != cc: raise Fail('child not slot start')
            if nodes[nid]['parent'] != nodes.index(n): raise Fail('parent mismatch')
    # owned counts bottom-up by stage
    order = sorted(range(len(nodes)), key=lambda i: nodes[i]['stage'])
    for idx in order:
        n = nodes[idx]
        if n['type'] == 4: owned = 1
        elif n['type'] == 5: owned = 2
        else: owned = bin(n['pattern']).count('1')
        for (key, cs, cc) in n['children']:
            owned += nodes[cover[cs][cc]]['owned']
        n['owned'] = owned
        if owned > 8192: raise Fail('owned bound')
        if n['type'] <= 3 and owned < 3: raise Fail('small subtree type%d owned %d' % (n['type'], owned))
        if n['type'] == 4 and owned != 1: raise Fail('type4 owned')
        if n['type'] == 5 and owned != 2: raise Fail('type5 owned')
    # distinct prefixes
    fs = sorted(fib, key=lambda x: (x[0], x[1]))
    for i in range(1, len(fs)):
        if fs[i][0] == fs[i - 1][0] and fs[i][1] == fs[i - 1][1]: raise Fail('duplicate prefix')
    if len(fs) > 8192: raise Fail('fib bound')
    # global BMP
    for n in nodes:
        want = None; bl = -1
        for (a, l, h) in fs:
            if l <= n['depth'] and mask(n['region'], l) == a and l > bl:
                want = h; bl = l
        wv = BMP_NULL if want is None else want
        if n['bmp'] != wv: raise Fail('bmp node depth %d want %s got %s' % (n['depth'], wv, n['bmp']))
    # NI dictionary
    used = sorted({n['pattern'] for n in nodes if n['type'] <= 3})
    if used != list(bitmaps): raise Fail('dictionary')
    mark = [0] * len(nexthops)
    for n in nodes:
        if n['type'] > 3: continue
        pc = bin(n['pattern']).count('1')
        if pc == 0:
            if n['ni_base'] != 0: raise Fail('empty base')
            continue
        for k in range(pc):
            if mark[n['ni_base'] + k]: raise Fail('ni overlap')
            mark[n['ni_base'] + k] = 1
    if any(m == 0 for m in mark): raise Fail('ni hole')
    # fronts complete
    has0 = any(l <= 16 for (a, l, h) in fs)
    k16 = sorted({a >> 112 for (a, l, h) in fs if 17 <= l <= 64})
    k64 = sorted({a >> 64 for (a, l, h) in fs if l >= 65})
    if has0 != (root is not None): raise Fail('root presence')
    if [int(e[0], 16) for e in f16] != k16: raise Fail('front16 completeness')
    if [int(e[0], 16) for e in f64] != k64: raise Fail('front64 completeness')
    return fs

def image_lookup(img, addr):
    """Walk a (already validated) image exactly as the loader would."""
    ok, reason, fs = validate_image(img, want_fib=True)
    if not ok: raise Fail('invalid image: ' + reason)
    return lpm(fs, addr)
